import{_ as a,o as d,c as e,ae as l}from"./chunks/framework.DNEY8DPf.js";const i="/cjrepo/docs/assets/admin_publish_step1.png",r="/cjrepo/docs/assets/admin_publish_step2.png",o="/cjrepo/docs/assets/admin_publish_step3.png",s="/cjrepo/docs/assets/admin_publishplan.png",n="/cjrepo/docs/assets/admin_publish_view.png",f=JSON.parse('{"title":"发布计划","description":"","frontmatter":{},"headers":[],"relativePath":"guide/publish-plan.md","filePath":"guide/publish-plan.md"}'),h={name:"guide/publish-plan.md"};function p(c,t,u,b,_,m){return d(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="发布计划" tabindex="-1">发布计划 <a class="header-anchor" href="#发布计划" aria-label="Permalink to &quot;发布计划&quot;">​</a></h1><p>发布计划功能允许用户将私有仓中的包批量发布到上游中心仓（如 pkg.cangjie-lang.cn），自动分析依赖树并按正确顺序发布。</p><h2 id="场景" tabindex="-1">场景 <a class="header-anchor" href="#场景" aria-label="Permalink to &quot;场景&quot;">​</a></h2><p>多包项目发布困难是常见痛点：</p><ul><li>包之间存在依赖关系，需要按顺序逐个发布</li><li>发布后需要等待上游索引更新才能继续下一个</li><li>依赖版本冲突难以排查</li><li>手动操作容易出错且耗时</li></ul><p>发布计划自动处理依赖分析、版本对比、索引轮询，简化多包发布流程。</p><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><ol><li>已配置上游源（<a href="/cjrepo/docs/guide/upstream.html">上游代理</a>），指向官方中心仓或其他 cjrepo 实例</li><li>上游源已配置发布 Token，有权限向目标仓发布包</li></ol><h2 id="创建发布计划" tabindex="-1">创建发布计划 <a class="header-anchor" href="#创建发布计划" aria-label="Permalink to &quot;创建发布计划&quot;">​</a></h2><p>点击左侧菜单「发布计划」→「新建计划」，进入三步向导。</p><h3 id="步骤-1-选择起始包" tabindex="-1">步骤 1：选择起始包 <a class="header-anchor" href="#步骤-1-选择起始包" aria-label="Permalink to &quot;步骤 1：选择起始包&quot;">​</a></h3><p><img src="'+i+'" alt="步骤1"></p><ul><li>选择目标上游（发布到哪个中心仓）</li><li>输入起始包，格式：<code>组织::包名@版本</code>（有组织）或 <code>包名@版本</code>（无组织）</li><li>支持添加多个起始包</li></ul><h3 id="步骤-2-分析依赖" tabindex="-1">步骤 2：分析依赖 <a class="header-anchor" href="#步骤-2-分析依赖" aria-label="Permalink to &quot;步骤 2：分析依赖&quot;">​</a></h3><p><img src="'+r+'" alt="步骤2"></p><p>点击「分析依赖」，系统会自动：</p><ol><li>递归解析各包的依赖树</li><li>去重合并</li><li>与上游中心仓对比版本和 SHA256</li></ol><p>分析结果按分类分组：</p><table tabindex="0"><thead><tr><th>分类</th><th>说明</th><th>默认操作</th></tr></thead><tbody><tr><td>🔴 冲突</td><td>版本号相同但 SHA256 不一致</td><td>需确认是否覆盖</td></tr><tr><td>🔴 需要发布</td><td>中心仓缺失该版本</td><td>默认选中</td></tr><tr><td>🟡 可选版本</td><td>依赖范围内有多个版本可选</td><td>用户勾选</td></tr><tr><td>⚪ 已存在</td><td>版本和 SHA256 与中心仓一致</td><td>跳过，不可选</td></tr></tbody></table><h3 id="步骤-3-确认并创建" tabindex="-1">步骤 3：确认并创建 <a class="header-anchor" href="#步骤-3-确认并创建" aria-label="Permalink to &quot;步骤 3：确认并创建&quot;">​</a></h3><p><img src="'+o+'" alt="步骤3"></p><ul><li>确认发布顺序（系统按依赖拓扑排序）</li><li>输入计划名称</li><li>可调整轮询间隔和超时时间</li><li>确认创建</li></ul><h2 id="查看执行状态" tabindex="-1">查看执行状态 <a class="header-anchor" href="#查看执行状态" aria-label="Permalink to &quot;查看执行状态&quot;">​</a></h2><p>从列表页进入详情页，实时查看发布进度。</p><p><img src="'+s+'" alt="列表"></p><p><img src="'+n+'" alt="详情"></p><p><strong>实时更新机制</strong>：</p><ul><li>使用 SSE（Server-Sent Events）推送状态变更</li><li>同时每 60 秒轮询兜底，确保不遗漏更新</li></ul><p><strong>状态说明</strong>：</p><table tabindex="0"><thead><tr><th>状态</th><th>图标</th><th>说明</th></tr></thead><tbody><tr><td>pending</td><td>⏳</td><td>等待发布</td></tr><tr><td>publishing</td><td>🔄</td><td>正在发布到上游</td></tr><tr><td>waiting_index</td><td>⏳</td><td>等待上游索引更新</td></tr><tr><td>completed</td><td>✅</td><td>发布完成</td></tr><tr><td>failed</td><td>❌</td><td>发布失败</td></tr><tr><td>skipped</td><td>⏭️</td><td>已跳过</td></tr></tbody></table><h2 id="计划控制" tabindex="-1">计划控制 <a class="header-anchor" href="#计划控制" aria-label="Permalink to &quot;计划控制&quot;">​</a></h2><ul><li><strong>开始</strong>：确认后手动触发执行</li><li><strong>暂停</strong>：暂停执行中的计划</li><li><strong>继续</strong>：恢复已暂停的计划</li><li><strong>删除</strong>：删除已完成或失败的计划</li></ul><h2 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to &quot;配置说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>轮询间隔</td><td>60 秒</td><td>每次轮询上游索引的等待时间</td></tr><tr><td>超时</td><td>自动计算</td><td>总超时 = 包数 × 间隔 × 5 × 2</td></tr></tbody></table>',34)])])}const q=a(h,[["render",p]]);export{f as __pageData,q as default};
